import { agencyAvatarSprites } from '@/data/agencyAvatarSprites';
import { douyinAvatarMap, douyinAvatarMeta } from '@/data/douyinAvatarMap';
import { useState } from 'react';

export function AgencyAvatar({ id, name }: { id: string; name: string }) {
  const avatar = agencyAvatarSprites[id] ?? douyinAvatarMap[id];
  const [failed, setFailed] = useState(false);
  const spriteSize = agencyAvatarSprites[id]?.spriteSize ??
    douyinAvatarMeta.spriteSize ?? [4000, 3200];
  const fallback = Array.from(name || '达人')
    .slice(0, 2)
    .join('');
  return (
    <span
      className="avatar avatar-photo"
      title={avatar && !failed ? `${name} 头像` : `${name}：暂无头像，姓名兜底`}
     data-aime-component-name="span"  data-aime-path-name="src/components/AgencyAvatar.tsx"  data-aime-column="5"  data-aime-line="14"  data-insp-path="src/components/AgencyAvatar.tsx:14:5:span" >
      {!failed && avatar?.avatarPosition ? (
        <span
          className="avatar-sprite"
          style={{
            backgroundImage: `url(${avatar.avatarUrl})`,
            backgroundPosition: avatar.avatarPosition,
            backgroundSize: `${spriteSize[0]}px ${spriteSize[1]}px`,
          }}
          role="img"
          aria-label={`${name} 头像`}
         data-aime-component-name="span"  data-aime-path-name="src/components/AgencyAvatar.tsx"  data-aime-column="9"  data-aime-line="19"  data-insp-path="src/components/AgencyAvatar.tsx:19:9:span" />
      ) : !failed && avatar?.avatarUrl ? (
        <img
          src={avatar.avatarUrl}
          alt={`${name} 头像`}
          onError={() => setFailed(true)}
         data-aime-component-name="img"  data-aime-path-name="src/components/AgencyAvatar.tsx"  data-aime-column="9"  data-aime-line="30"  data-insp-path="src/components/AgencyAvatar.tsx:30:9:img" />
      ) : (
        <span data-aime-component-name="span" data-aime-path-name="src/components/AgencyAvatar.tsx" data-aime-column="9" data-aime-line="36" data-insp-path="src/components/AgencyAvatar.tsx:36:9:span">{fallback}</span>
      )}
    </span>
  );
}
