import { INDUSTRY_OPTIONS, INDUSTRY_TOTAL } from '../data/industryOptions';

const RADIUS = 72;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

export function IndustryShareDonut() {
  let accumulated = 0;

  return (
    <div
      className="industry-share-donut"
      role="img"
      aria-label={`11 个重点行业供给占比，总供给 ${INDUSTRY_TOTAL.toLocaleString()} 位达人`}
     data-aime-component-name="div"  data-aime-path-name="src/components/IndustryShareDonut.tsx"  data-aime-column="5"  data-aime-line="10"  data-insp-path="src/components/IndustryShareDonut.tsx:10:5:div" >
      <svg viewBox="0 0 180 180" aria-hidden="true" data-aime-component-name="svg"  data-aime-path-name="src/components/IndustryShareDonut.tsx"  data-aime-column="7"  data-aime-line="15"  data-insp-path="src/components/IndustryShareDonut.tsx:15:7:svg" >
        <circle
          className="industry-share-track"
          cx="90"
          cy="90"
          r={RADIUS}
          fill="none"
          strokeWidth="18"
         data-aime-component-name="circle"  data-aime-path-name="src/components/IndustryShareDonut.tsx"  data-aime-column="9"  data-aime-line="16"  data-insp-path="src/components/IndustryShareDonut.tsx:16:9:circle" />
        {INDUSTRY_OPTIONS.map(industry => {
          const segmentLength =
            (industry.count / INDUSTRY_TOTAL) * CIRCUMFERENCE;
          const offset = -accumulated;
          accumulated += segmentLength;
          const percent = ((industry.count / INDUSTRY_TOTAL) * 100).toFixed(1);

          return (
            <circle
              key={industry.id}
              cx="90"
              cy="90"
              r={RADIUS}
              fill="none"
              stroke={industry.color}
              strokeWidth="18"
              strokeDasharray={`${segmentLength} ${CIRCUMFERENCE - segmentLength}`}
              strokeDashoffset={offset}
             data-aime-component-name="circle"  data-aime-path-name="src/components/IndustryShareDonut.tsx"  data-aime-column="13"  data-aime-line="32"  data-insp-path="src/components/IndustryShareDonut.tsx:32:13:circle" >
              <title data-aime-component-name="title" data-aime-path-name="src/components/IndustryShareDonut.tsx" data-aime-column="15" data-aime-line="43" data-insp-path="src/components/IndustryShareDonut.tsx:43:15:title">
                {industry.label}：{industry.count.toLocaleString()}（{percent}
                %）
              </title>
            </circle>
          );
        })}
      </svg>
      <div className="industry-share-center" data-aime-component-name="div"  data-aime-path-name="src/components/IndustryShareDonut.tsx"  data-aime-column="7"  data-aime-line="51"  data-insp-path="src/components/IndustryShareDonut.tsx:51:7:div" >
        <strong data-aime-component-name="strong" data-aime-path-name="src/components/IndustryShareDonut.tsx" data-aime-column="9" data-aime-line="52" data-insp-path="src/components/IndustryShareDonut.tsx:52:9:strong">{INDUSTRY_TOTAL.toLocaleString()}</strong>
        <span data-aime-component-name="span" data-aime-path-name="src/components/IndustryShareDonut.tsx" data-aime-column="9" data-aime-line="53" data-insp-path="src/components/IndustryShareDonut.tsx:53:9:span">总供给</span>
      </div>
    </div>
  );
}
