import { agencyPagination } from '@/lib/agencyPagination';

export function AgencyPager({
  total,
  page,
  onChange,
  ariaLabel = '代理商重点分页',
}: {
  total: number;
  page: number;
  onChange: (page: number) => void;
  ariaLabel?: string;
}) {
  const data = agencyPagination(total, page);
  const buttonClass =
    'rounded-lg border border-slate-600 px-3 py-2 text-sm disabled:opacity-40 disabled:cursor-not-allowed';
  return (
    <nav
      aria-label={ariaLabel}
      className="flex flex-wrap gap-2 items-center my-4"
     data-aime-component-name="nav"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="5"  data-aime-line="18"  data-insp-path="src/components/AgencyPager.tsx:18:5:nav" >
      <span className="text-sm mr-2" aria-live="polite" data-aime-component-name="span"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="7"  data-aime-line="22"  data-insp-path="src/components/AgencyPager.tsx:22:7:span" >
        共 {total.toLocaleString()} 条 · 第 {data.page} / {data.totalPages} 页 ·
        展示 {data.start}–{data.end} 条
      </span>
      <button
        className={buttonClass}
        disabled={data.page === 1 || !total}
        onClick={() => onChange(data.page - 1)}
       data-aime-component-name="button"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="7"  data-aime-line="26"  data-insp-path="src/components/AgencyPager.tsx:26:7:button" >
        上一页
      </button>
      {data.pageNumbers.map((n, i) => (
        <span key={n} className="flex gap-2 items-center" data-aime-component-name="span"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="9"  data-aime-line="34"  data-insp-path="src/components/AgencyPager.tsx:34:9:span" >
          {i > 0 && n - data.pageNumbers[i - 1] > 1 && (
            <span aria-hidden="true" data-aime-component-name="span"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="13"  data-aime-line="36"  data-insp-path="src/components/AgencyPager.tsx:36:13:span" >…</span>
          )}
          <button
            className={`${buttonClass} ${n === data.page ? 'bg-cyan-900 text-cyan-200' : ''}`}
            aria-label={`第 ${n} 页`}
            aria-current={n === data.page ? 'page' : undefined}
            disabled={!total}
            onClick={() => onChange(n)}
           data-aime-component-name="button"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="11"  data-aime-line="38"  data-insp-path="src/components/AgencyPager.tsx:38:11:button" >
            {n}
          </button>
        </span>
      ))}
      <button
        className={buttonClass}
        disabled={data.page >= data.totalPages || !total}
        onClick={() => onChange(data.page + 1)}
       data-aime-component-name="button"  data-aime-path-name="src/components/AgencyPager.tsx"  data-aime-column="7"  data-aime-line="49"  data-insp-path="src/components/AgencyPager.tsx:49:7:button" >
        下一页
      </button>
    </nav>
  );
}
